def code(t):
 import textwrap
 lines=[]
 for line in t.splitlines():
  parts=textwrap.wrap(line,width=100,break_long_words=False,break_on_hyphens=False) or ['']
  lines.extend(part+(' `' if i<len(parts)-1 else '') for i,part in enumerate(parts))
